 * With a clone batch, resets progress and writes the new project and issues
 * atomically instead. The service checks permissions and quotas first.
 */
export async function duplicateProject(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  slug: string,
  key: string,
  clone?: {
    copies: readonly Issue[];
    authorId: UserId;
    status: IssueStatus;
  },
): Promise<Project> {
  const source = getDb()
    .select()
    .from(projects)
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .get();
  if (!source) throw new Error(`Project ${projectId} not found`);

  if (clone) {
    return insertProjectClone(
      { orgId, name, slug, key },
      toProject(source),
      clone.copies,
      clone.authorId,
      clone.status,
    );
  }

  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(projects)
    .values({
      ...source,
      id: newId(),
      name,
      slug,
      key,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toProject(row);
}

